CREATE TABLE invoices (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, client_id BIGINT UNSIGNED NOT NULL, project_id BIGINT UNSIGNED NULL, quote_id BIGINT UNSIGNED NULL, created_by_user_id BIGINT UNSIGNED NULL, invoice_number VARCHAR(50) NOT NULL, issue_date DATE NOT NULL, due_date DATE NULL, paid_date DATE NULL,
 status ENUM('draft','sent','partially_paid','paid','overdue','cancelled') NOT NULL DEFAULT 'draft', subtotal DECIMAL(15,2) NOT NULL DEFAULT 0.00, tax_amount DECIMAL(15,2) NOT NULL DEFAULT 0.00, total_amount DECIMAL(15,2) GENERATED ALWAYS AS (subtotal + tax_amount) STORED, notes TEXT NULL,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_invoices_number (invoice_number), KEY idx_invoices_client_status (client_id,status), KEY idx_invoices_project (project_id),
 CONSTRAINT chk_invoice_amounts CHECK (subtotal >= 0 AND tax_amount >= 0), CONSTRAINT chk_invoice_due_date CHECK (due_date IS NULL OR due_date >= issue_date), CONSTRAINT chk_invoice_paid_date CHECK (paid_date IS NULL OR paid_date >= issue_date), CONSTRAINT fk_invoices_client FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE RESTRICT, CONSTRAINT fk_invoices_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE RESTRICT, CONSTRAINT fk_invoices_quote FOREIGN KEY (quote_id) REFERENCES quotes(id) ON DELETE RESTRICT, CONSTRAINT fk_invoices_user FOREIGN KEY (created_by_user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
